package mekanism.common.lib.frequency;

import com.mojang.datafixers.Products.P3;
import com.mojang.serialization.codecs.RecordCodecBuilder.Instance;
import com.mojang.serialization.codecs.RecordCodecBuilder.Mu;
import io.netty.buffer.ByteBuf;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import mekanism.api.IFrequency;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.network.PacketUtils;
import mekanism.common.util.MekanismUtils;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import org.jspecify.annotations.Nullable;

public abstract class Frequency implements IFrequency {

    protected static <FREQ extends Frequency> P3<Mu<FREQ>, String, Optional<UUID>, SecurityMode> baseCodec(Instance<FREQ> instance) {
        return instance.group(
              ExtraCodecs.NON_EMPTY_STRING.fieldOf(SerializationConstants.NAME).forGetter(Frequency::getName),
              UUIDUtil.CODEC.optionalFieldOf(SerializationConstants.OWNER_UUID).forGetter(freq -> Optional.ofNullable(freq.getOwner())),
              SecurityMode.CODEC.fieldOf(SerializationConstants.SECURITY_MODE).forGetter(Frequency::getSecurity)
        );
    }

    protected static <BUF extends ByteBuf, FREQ extends Frequency> StreamCodec<BUF, FREQ> baseStreamCodec(FrequencyConstructor<FREQ> constructor) {
        return StreamCodec.composite(
              ByteBufCodecs.STRING_UTF8, Frequency::getName,
              ByteBufCodecs.optional(UUIDUtil.STREAM_CODEC), freq -> Optional.ofNullable(freq.getOwner()),
              ByteBufCodecs.stringUtf8(PacketUtils.LAST_USERNAME_LENGTH), Frequency::getOwnerName,
              SecurityMode.STREAM_CODEC, Frequency::getSecurity,
              (name, owner, ownerName, security) -> constructor.create(name, owner.orElse(null), ownerName, security)
        );
    }

    protected boolean dirty;
    private boolean removed;
    private final String name;

    @Nullable
    private final UUID ownerUUID;
    private final String ownerName;

    private boolean valid = true;
    private SecurityMode securityMode;

    private final FrequencyType<?> frequencyType;

    /// Owner username is looked up so that we can sync it (and more importantly have it set in single player when network connections don't serialize and deserialize)
    ///
    /// @param owner Should only be null if we have incomplete data that we are loading.
    protected Frequency(FrequencyType<?> frequencyType, String name, @Nullable UUID owner, SecurityMode securityMode) {
        this(frequencyType, name, owner, MekanismUtils.getLastKnownUsername(owner), securityMode);
    }

    protected Frequency(FrequencyType<?> frequencyType, String name, @Nullable UUID owner, String ownerName, SecurityMode securityMode) {
        this.frequencyType = frequencyType;
        this.name = name;
        this.ownerUUID = owner;
        this.ownerName = ownerName;
        this.securityMode = securityMode;
    }

    public void onRemove() {
        removed = true;
    }

    public boolean isRemoved() {
        return removed;
    }

    /// @return `true` if persistent data was changed by deactivating the block and the frequency needs to be saved.
    public boolean onDeactivate(Level level, BlockEntity tile) {
        return false;
    }

    /// @return `true` if persistent data was changed by updating the block and the frequency needs to be saved.
    public boolean update(Level level, BlockEntity tile) {
        return false;
    }

    public FrequencyType<?> getType() {
        return frequencyType;
    }

    public Object getKey() {
        return name;
    }

    @Override
    public final SecurityMode getSecurity() {
        return securityMode;
    }

    public void setSecurityMode(SecurityMode securityMode) {
        if (this.securityMode != securityMode) {
            this.securityMode = securityMode;
            dirty = true;
        }
    }

    @Override
    public boolean isValid() {
        return valid;
    }

    public void setValid(boolean valid) {
        this.valid = valid;
    }

    @Override
    public String getName() {
        return name;
    }

    @Nullable
    @Override
    public UUID getOwner() {
        return ownerUUID;
    }

    public boolean ownerMatches(UUID toCheck) {
        return Objects.equals(ownerUUID, toCheck);
    }

    public String getOwnerName() {
        return ownerName;
    }

    /// This is the hashCode that is used for determining if a frequency is dirty. Override this if your frequency type has more things that may mean it needs to be
    /// re-synced.
    public int getSyncHash() {
        return hashCode();
    }

    @Override
    public int hashCode() {
        int code = 1;
        code = 31 * code + name.hashCode();
        if (ownerUUID != null) {
            code = 31 * code + ownerUUID.hashCode();
        }
        if (frequencyType != FrequencyTypes.SECURITY) {
            code = 31 * code + securityMode.ordinal();
        }
        return code;
    }

    @Override
    public boolean equals(@Nullable Object obj) {
        if (this == obj) {
            return true;
        }
        if (obj instanceof Frequency other) {
            if (frequencyType == FrequencyTypes.SECURITY || securityMode == other.securityMode) {
                return ownerUUID != null && name.equals(other.name) && ownerUUID.equals(other.ownerUUID);
            }
        }
        return false;
    }

    public FrequencyIdentity getIdentity() {
        return new FrequencyIdentity(getKey(), securityMode, ownerUUID);
    }

    public record FrequencyIdentity(Object key, SecurityMode securityMode, @Nullable UUID ownerUUID) {
    }

    @FunctionalInterface
    protected interface FrequencyConstructor<FREQ extends Frequency> {

        FREQ create(String name, @Nullable UUID owner, String ownerName, SecurityMode securityMode);
    }
}

package mekanism.common.lib.security;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import io.netty.buffer.ByteBuf;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.lib.collection.HashList;
import mekanism.common.lib.frequency.Frequency;
import mekanism.common.lib.frequency.FrequencyTypes;
import mekanism.common.network.PacketUtils;
import mekanism.common.util.MekanismUtils;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import org.jspecify.annotations.Nullable;

public class SecurityFrequency extends Frequency {

    public static final String SECURITY = "Security";

    public static final Codec<SecurityFrequency> CODEC = RecordCodecBuilder.create(instance -> instance.group(
          UUIDUtil.CODEC.optionalFieldOf(SerializationConstants.OWNER_UUID).forGetter(freq -> Optional.ofNullable(freq.getOwner())),
          SecurityMode.CODEC.fieldOf(SerializationConstants.SECURITY_MODE).forGetter(SecurityFrequency::getSecurity),
          Codec.BOOL.fieldOf(SerializationConstants.OVERRIDE).forGetter(SecurityFrequency::isOverridden),
          UUIDUtil.CODEC.listOf().optionalFieldOf(SerializationConstants.TRUSTED).forGetter(freq -> freq.trusted.isEmpty() ? Optional.empty() : Optional.of(freq.trusted.elements()))
    ).apply(instance, (owner, securityMode, override, trustedCache) -> {
        SecurityFrequency frequency = new SecurityFrequency(owner.orElse(null), securityMode);
        frequency.override = override;
        for (UUID trusted : trustedCache.orElse(Collections.emptyList())) {
            frequency.addTrustedRaw(trusted, MekanismUtils.getLastKnownUsername(trusted));
        }
        return frequency;
    }));
    public static final StreamCodec<ByteBuf, SecurityFrequency> STREAM_CODEC = StreamCodec.composite(
          ByteBufCodecs.optional(UUIDUtil.STREAM_CODEC), freq -> Optional.ofNullable(freq.getOwner()),
          ByteBufCodecs.stringUtf8(PacketUtils.LAST_USERNAME_LENGTH), SecurityFrequency::getOwnerName,
          SecurityMode.STREAM_CODEC, SecurityFrequency::getSecurity,
          ByteBufCodecs.BOOL, SecurityFrequency::isOverridden,
          ByteBufCodecs.stringUtf8(PacketUtils.LAST_USERNAME_LENGTH).<HashList<String>>apply(buf -> ByteBufCodecs.collection(HashList::new, buf)), freq -> freq.trustedCache,
          (owner, ownerName, securityMode, override, trustedCache) -> {
              SecurityFrequency frequency = new SecurityFrequency(owner.orElse(null), ownerName, securityMode);
              frequency.override = override;
              frequency.trustedCache = trustedCache;
              return frequency;
          }
    );

    private boolean override = false;

    private final HashList<UUID> trusted = new HashList<>();
    private HashList<String> trustedCache = new HashList<>();
    private int trustedCacheHash;

    /// @param uuid Should only be null if we have incomplete data that we are loading
    public SecurityFrequency(@Nullable UUID uuid, SecurityMode securityMode) {
        super(FrequencyTypes.SECURITY, SECURITY, uuid, securityMode);
    }

    private SecurityFrequency(@Nullable UUID owner, String ownerName, SecurityMode securityMode) {
        super(FrequencyTypes.SECURITY, SECURITY, owner, ownerName, securityMode);
    }

    @Override
    public UUID getKey() {
        return getOwner();
    }

    @Override
    public int getSyncHash() {
        int code = super.getSyncHash();
        code = 31 * code + (override ? 1 : 0);
        //We skip including the security in the normal hashcode, but we do need to include it in the sync hashcode
        code = 31 * code + getSecurity().ordinal();
        code = 31 * code + trustedCacheHash;
        return code;
    }

    public void setOverridden(boolean override) {
        if (this.override != override) {
            this.override = override;
            this.dirty = true;
        }
    }

    @Override
    public FrequencyIdentity getIdentity() {
        return new FrequencyIdentity(getKey(), SecurityMode.PUBLIC, getOwner());
    }

    public boolean isOverridden() {
        return override;
    }

    public boolean isTrusted(UUID subject) {
        return trusted.contains(subject);
    }

    public List<String> getTrustedUsernameCache() {
        return trustedCache.elements();
    }

    public void addTrusted(UUID uuid, String name) {
        if (!trusted.contains(uuid)) {
            addTrustedRaw(uuid, name);
            this.dirty = true;
        }
    }

    private void addTrustedRaw(UUID uuid, String name) {
        trusted.add(uuid);
        trustedCache.add(name);
        trustedCacheHash = trustedCache.hashCode();
    }

    @Nullable
    public UUID removeTrusted(int index) {
        UUID uuid = null;
        if (index >= 0 && index < trusted.size()) {
            uuid = trusted.remove(index);
            this.dirty = true;
        }
        if (index >= 0 && index < trustedCache.size()) {
            trustedCache.remove(index);
            trustedCacheHash = trustedCache.hashCode();
        }
        return uuid;
    }
}

package mekanism.common.lib.frequency;

import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.function.Consumer;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.Mekanism;
import mekanism.common.content.qio.TickableFrequency;
import mekanism.common.lib.frequency.Frequency.FrequencyIdentity;
import mekanism.common.lib.security.SecurityFrequency;
import net.minecraft.core.UUIDUtil;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.saveddata.SavedData;
import org.jspecify.annotations.Nullable;

/// Stores a map of Identity to Frequency (Data)
public class FrequencyLookup<FREQ extends Frequency> extends SavedData {

    public static final int MAX_FREQ_LENGTH = 16;

    private final Map<Object, FREQ> frequencies = new LinkedHashMap<>();

    @Nullable
    private final UUID ownerUUID;

    private final FrequencyType<FREQ> frequencyType;
    private final SecurityMode securityMode;

    public FrequencyLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode) {
        this(frequencyType, uuid, securityMode, Collections.emptyList());
    }

    private FrequencyLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode, List<FREQ> loadedFrequencies) {
        this.frequencyType = frequencyType;
        ownerUUID = uuid;
        this.securityMode = securityMode;
        for (FREQ loadedFrequency : loadedFrequencies) {
            frequencies.put(loadedFrequency.getKey(), loadedFrequency);
        }
    }

    @Nullable
    public UUID getOwnerUUID() {
        return ownerUUID;
    }

    public FrequencyType<FREQ> getFrequencyType() {
        return frequencyType;
    }

    public boolean remove(Object key, UUID ownerUUID) {
        FREQ freq = getFrequency(key);
        if (freq != null && freq.ownerMatches(ownerUUID)) {
            freq.onRemove();
            frequencies.remove(key);
            setDirty();
            return true;
        }
        return false;
    }

    public void deactivate(@Nullable Frequency freq, Level level, BlockEntity tile) {
        if (freq != null && freq.onDeactivate(level, tile)) {
            setDirty();
        }
    }

    public FREQ validateAndUpdate(Level level, BlockEntity tile, FREQ freq) {
        FREQ storedFreq = frequencies.get(freq.getKey());
        if (storedFreq == null) {
            freq.setValid(true);
            setDirty();
            frequencies.put(freq.getKey(), freq);
            storedFreq = freq;
        }
        if (storedFreq.update(level, tile)) {
            setDirty();
        }
        return storedFreq;
    }

    public Collection<FREQ> getFrequencies() {
        if (securityMode == SecurityMode.TRUSTED && ownerUUID != null) {
            //TODO: Try to come up with a better way of doing this that allows us to cache this
            FrequencyLookup<SecurityFrequency> securityLookup = FrequencyTypes.SECURITY.getLookup(null, SecurityMode.PUBLIC);
            if (securityLookup == null) {
                return Collections.emptyList();
            }
            List<FREQ> trustedFrequencies = new ArrayList<>(frequencies.values());
            for (FrequencyLookup<FREQ> trustedLookup : frequencyType.getController().getTrustedLookups()) {
                if (!ownerUUID.equals(trustedLookup.ownerUUID)) {
                    //Add any frequencies that the owner has access to because of being trusted by the other player
                    SecurityFrequency frequency = securityLookup.getFrequency(trustedLookup.ownerUUID);
                    if (frequency != null && frequency.isTrusted(ownerUUID)) {
                        trustedFrequencies.addAll(trustedLookup.frequencies.values());
                    }
                }
            }
            return trustedFrequencies;
        }
        return frequencies.values();
    }

    @Nullable
    public FREQ getFrequency(@Nullable Object key) {
        return key == null ? null : frequencies.get(key);
    }

    public FREQ getOrCreateFrequency(FrequencyIdentity identity, @Nullable UUID ownerUUID) {
        FREQ freq = frequencies.get(identity.key());
        if (freq == null) {
            freq = frequencyType.create(identity.key(), ownerUUID, identity.securityMode());
            frequencies.put(identity.key(), freq);
            setDirty();
        }
        return freq;
    }

    public void addFrequency(FREQ freq) {
        frequencies.put(freq.getKey(), freq);
        setDirty();
    }

    public FrequencyType<FREQ> getType() {
        return frequencyType;
    }

    public void tickSelf(boolean tickingNormally) {
        boolean dirty = false;
        for (FREQ freq : frequencies.values()) {
            dirty |= ((TickableFrequency) freq).tick(tickingNormally);
        }
        if (dirty) {
            setDirty();
        }
    }

    public static Identifier getId(@Nullable UUID ownerUUID, SecurityMode securityMode, FrequencyType<?> frequencyType) {
        StringBuilder path = new StringBuilder("frequency/");
        path.append(frequencyType.getName()).append("/");
        if (ownerUUID != null) {
            path.append(ownerUUID.toString().toLowerCase(Locale.ROOT)).append("/");
        }
        path.append(securityMode.getSerializedName());
        return Mekanism.rl(path.toString());
    }

    private static final Consumer<String> frequencyError = err -> Mekanism.logger.error("Failed to load some frequencies: {}", err);

    public static <FREQ extends Frequency> Codec<Pair<Optional<UUID>, List<FREQ>>> baseCodec(FrequencyType<FREQ> frequencyType) {
        return RecordCodecBuilder.create(instance -> instance.group(
              UUIDUtil.CODEC.optionalFieldOf(SerializationConstants.OWNER_UUID).forGetter(Pair::getFirst),
              frequencyType.codec().listOf().promotePartial(frequencyError).fieldOf(SerializationConstants.FREQUENCY_LIST).forGetter(Pair::getSecond)
        ).apply(instance, Pair::new));
    }

    public static <FREQ extends Frequency> Codec<FrequencyLookup<FREQ>> codec(FrequencyType<FREQ> frequencyType, Codec<Pair<Optional<UUID>, List<FREQ>>> baseCodec, SecurityMode securityMode) {
        return baseCodec.xmap(
              pair -> new FrequencyLookup<>(frequencyType, pair.getFirst().orElse(null), securityMode, pair.getSecond()),
              lookup -> Pair.of(Optional.ofNullable(lookup.getOwnerUUID()), new ArrayList<>(lookup.frequencies.values()))
        );
    }
}

package mekanism.common.lib.frequency;

import com.mojang.serialization.Codec;
import io.netty.buffer.ByteBuf;
import io.netty.handler.codec.DecoderException;
import java.util.Objects;
import java.util.UUID;
import mekanism.api.security.SecurityMode;
import mekanism.common.lib.frequency.Frequency.FrequencyIdentity;
import mekanism.common.lib.frequency.FrequencyController.Type;
import mekanism.common.lib.frequency.FrequencyTypes.FrequencyConstructor;
import mekanism.common.lib.security.SecurityUtils;
import mekanism.common.util.MekCodecs;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.neoforged.neoforge.network.codec.NeoForgeStreamCodecs;
import org.jetbrains.annotations.Contract;
import org.jspecify.annotations.Nullable;

public class FrequencyType<FREQ extends Frequency> {

    //TODO - 26.3 - investigate no usages
    public static final Codec<FrequencyType<?>> CODEC = MekCodecs.stringResolver(FrequencyType::getName, FrequencyTypes::byName);
    public static final StreamCodec<ByteBuf, FrequencyType<?>> STREAM_CODEC = NeoForgeStreamCodecs.lazy(() -> ByteBufCodecs.stringUtf8(255).map(
          name -> {
              FrequencyType<?> type = FrequencyTypes.byName(name);
              if (type == null) {
                  throw new DecoderException("Unable to find frequency type for name: " + name);
              }
              return type;
          }, FrequencyType::getName
    ));

    private final String name;
    private final FrequencyConstructor<FREQ> creationFunction;
    private final Codec<FREQ> codec;
    private final StreamCodec<? super RegistryFriendlyByteBuf, FREQ> streamCodec;
    private final IdentitySerializer identitySerializer;
    private final FrequencyController.Type controllerType;
    private final boolean needsTick;

    public FrequencyType(String name, FrequencyConstructor<FREQ> creationFunction, Codec<FREQ> codec, StreamCodec<? super RegistryFriendlyByteBuf, FREQ> streamCodec,
          FrequencyController.Type controllerType, IdentitySerializer identitySerializer, boolean needsTick) {
        this.name = name;
        this.creationFunction = creationFunction;
        this.codec = codec;
        this.streamCodec = streamCodec;
        this.controllerType = controllerType;
        this.identitySerializer = identitySerializer;
        this.needsTick = needsTick;
    }

    public String getName() {
        return name;
    }

    public StreamCodec<? super RegistryFriendlyByteBuf, FREQ> streamCodec() {
        return streamCodec;
    }

    public Codec<FREQ> codec() {
        return codec;
    }

    public Type getControllerType() {
        return controllerType;
    }

    @Nullable
    public FREQ create(FrequencyIdentity identity) {
        FREQ frequency = create(identity.key(), identity.ownerUUID(), identity.securityMode());
        frequency.setValid(false);
        return frequency;
    }

    public FREQ create(Object key, @Nullable UUID ownerUUID, SecurityMode securityMode) {
        return creationFunction.create(key, ownerUUID, securityMode);
    }

    public FrequencyController<FREQ> getController() {
        return FrequencyControllerManager.getController(this);
    }

    @Nullable
    public FREQ getFrequency(@Nullable UUID owner, SecurityMode securityMode, @Nullable Object key) {
        FrequencyLookup<FREQ> lookup = getLookup(owner, securityMode);
        return lookup == null ? null : lookup.getFrequency(key);
    }

    @Nullable
    public FrequencyLookup<FREQ> getLookup(@Nullable UUID owner, SecurityMode securityMode) {
        return switch (securityMode) {
            case PUBLIC -> getController().getPublicLookup();
            case PRIVATE -> getController().getPrivateLookup(owner);
            case TRUSTED -> getController().getTrustedLookup(owner);
        };
    }

    @Nullable
    @Contract("null -> null")
    public FrequencyLookup<FREQ> getFrequencyLookup(@Nullable FREQ freq) {
        if (freq == null) {
            return null;
        }
        FrequencyController<FREQ> controller = getController();
        if (freq.getType() == FrequencyTypes.SECURITY) {
            //Frequency#getSecurity means something slightly different for security frequencies. They are always public
            return controller.getPublicLookup();
        }
        return switch (freq.getSecurity()) {
            case PUBLIC -> controller.getPublicLookup();
            case PRIVATE -> controller.getPrivateLookup(freq.getOwner());
            case TRUSTED -> controller.getTrustedLookup(freq.getOwner());
        };
    }

    @Nullable
    public FrequencyLookup<FREQ> getLookup(FrequencyIdentity identity, @Nullable UUID owner) {
        return switch (identity.securityMode()) {
            case PUBLIC -> getController().getPublicLookup();
            case PRIVATE -> getController().getPrivateLookup(owner);
            case TRUSTED -> getController().getTrustedLookup(owner);
        };
    }

    @Nullable
    public FREQ getFrequency(FrequencyIdentity identity, UUID owner) {
        FrequencyLookup<FREQ> lookup;
        if (!Objects.equals(identity.ownerUUID(), owner) && SecurityUtils.get().isTrusted(identity.securityMode(), identity.ownerUUID(), owner)) {
            lookup = getLookup(identity, identity.ownerUUID());
        } else {
            lookup = getLookup(identity, owner);
        }
        return lookup == null ? null : lookup.getFrequency(identity.key());
    }

    public IdentitySerializer getIdentitySerializer() {
        return identitySerializer;
    }

    @Override
    public String toString() {
        return name;
    }

    @Override
    public int hashCode() {
        return name.hashCode();
    }

    @Override
    public boolean equals(@Nullable Object obj) {
        return super.equals(obj) || (obj instanceof FrequencyType<?> other && Objects.equals(name, other.name));
    }

    public boolean needsTick() {
        return needsTick;
    }
}

package mekanism.common.lib.frequency;

import com.mojang.serialization.Codec;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import mekanism.api.SerializationConstants;
import mekanism.api.security.SecurityMode;
import mekanism.common.Mekanism;
import mekanism.common.content.entangloporter.InventoryFrequency;
import mekanism.common.content.qio.QIOFrequency;
import mekanism.common.content.teleporter.TeleporterFrequency;
import mekanism.common.lib.security.SecurityFrequency;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import org.jspecify.annotations.Nullable;

public class FrequencyTypes {
    private static final Map<String, FrequencyType<?>> registryMap = new HashMap<>();

    public static final FrequencyType<TeleporterFrequency> TELEPORTER = register("teleporter",
          (key, uuid, securityMode) -> new TeleporterFrequency((String) key, uuid, securityMode),
          TeleporterFrequency.CODEC,
          TeleporterFrequency.STREAM_CODEC,
          FrequencyController.Type.PUBLIC_PRIVATE_TRUSTED,
          IdentitySerializer.NAME,
          false);
    public static final FrequencyType<InventoryFrequency> INVENTORY = register("inventory",
          (key, uuid, securityMode) -> new InventoryFrequency((String) key, uuid, securityMode),
          InventoryFrequency.CODEC,
          InventoryFrequency.STREAM_CODEC,
          FrequencyController.Type.PUBLIC_PRIVATE_TRUSTED,
          IdentitySerializer.NAME,
          false);
    public static final FrequencyType<SecurityFrequency> SECURITY = register("security",
          (key, uuid, securityMode) -> new SecurityFrequency(uuid, securityMode),
          SecurityFrequency.CODEC,
          SecurityFrequency.STREAM_CODEC,
          FrequencyController.Type.PUBLIC_ONLY,
          IdentitySerializer.UUID,
          false);
    public static final FrequencyType<QIOFrequency> QIO = register("qio",
          (key, uuid, securityMode) -> new QIOFrequency((String) key, uuid, securityMode),
          QIOFrequency.CODEC,
          QIOFrequency.STREAM_CODEC,
          FrequencyController.Type.PUBLIC_PRIVATE_TRUSTED,
          IdentitySerializer.NAME,
          true);

    /// Exists as a tidy way of controlling classload and 'registering' the Types.
    public static void init() {
        Mekanism.logger.debug("Initialising FrequencyTypes");
    }

    private static <FREQ extends Frequency> FrequencyType<FREQ> register(String name, FrequencyConstructor<FREQ> creationFunction, Codec<FREQ> codec,
          StreamCodec<? super RegistryFriendlyByteBuf, FREQ> streamCodec, FrequencyController.Type managerType, IdentitySerializer identitySerializer, boolean needsTick) {
        FrequencyType<FREQ> type = new FrequencyType<>(name, creationFunction, codec, streamCodec, managerType, identitySerializer, needsTick);
        registryMap.put(name, type);
        return type;
    }

    //TODO - 26.3 - investigate why no usages, remove?
    public static <FREQ extends Frequency> FrequencyType<FREQ> load(CompoundTag tag) {
        return (FrequencyType<FREQ>) registryMap.get(tag.getString(SerializationConstants.TYPE));
    }

    @Nullable
    public static FrequencyType<?> byName(String name) {
        return registryMap.get(name);
    }

    public static Collection<FrequencyType<?>> allRegistered() {
        return Collections.unmodifiableCollection(registryMap.values());
    }

    @FunctionalInterface
    public interface FrequencyConstructor<FREQ extends Frequency> {

        FREQ create(Object key, @Nullable UUID owner, SecurityMode securityMode);
    }
}

package mekanism.common.lib.frequency;

import com.mojang.serialization.Codec;
import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import mekanism.api.security.SecurityMode;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedDataType;
import net.minecraft.world.level.storage.SavedDataStorage;
import org.jspecify.annotations.Nullable;

public class FrequencyControllerManager {

    static final List<FrequencyLookup<?>> tickableLookups = new ArrayList<>();
    @Nullable
    private static SavedDataStorage dataStorage = null;
    private static final Map<FrequencyType<?>, FrequencyController<?>> controllers = new IdentityHashMap<>(FrequencyTypes.allRegistered().size());

    public static void serverLoad(MinecraftServer server) {
        dataStorage = server.getDataStorage();
        for (FrequencyType<?> frequencyType : FrequencyTypes.allRegistered()) {
            controllers.put(frequencyType, FrequencyController.create(frequencyType));
        }
    }

    public static void reset() {
        dataStorage = null;
        tickableLookups.clear();
        controllers.clear();
    }

    @SuppressWarnings("unchecked")
    public static <FREQ extends Frequency> FrequencyController<FREQ> getController(FrequencyType<FREQ> frequencyType) {
        return (FrequencyController<FREQ>) controllers.get(frequencyType);
    }

    protected static <FREQ extends Frequency> FrequencyLookup<FREQ> createLookup(FrequencyType<FREQ> frequencyType, @Nullable UUID uuid, SecurityMode securityMode, Codec<FrequencyLookup<FREQ>> codec) {
        FrequencyLookup<FREQ> lookup;
        if (dataStorage == null) {
            //assume client - TODO - 26.3 - does this even get called on the client? seems not
            lookup = new FrequencyLookup<>(frequencyType, uuid, securityMode);
        } else {
            SavedDataType<FrequencyLookup<FREQ>> dataType = new SavedDataType<>(
                  FrequencyLookup.getId(uuid, securityMode, frequencyType),
                  () -> new FrequencyLookup<>(frequencyType, uuid, securityMode),
                codec
            );
            lookup = dataStorage.computeIfAbsent(dataType);
        }
        registerTickable(lookup);
        return lookup;
    }

    public static void registerTickable(FrequencyLookup<?> lookup) {
        if (lookup.getFrequencyType().needsTick()) {
            tickableLookups.add(lookup);
        }
    }

    public static void tick(boolean tickingNormally) {
        for (FrequencyLookup<?> lookup : tickableLookups) {
            lookup.tickSelf(tickingNormally);
        }
    }
}

